// src/commands/generate.ts
function renderBlock(type, config) {
  switch (type) {
    case "tailwind-js":
      return generateTailwindJs(config.tokens);
    case "theme-ts":
      return generateThemeTs(config.tokens);
    case "globals-css":
      return generateGlobalsCss(config.tokens);
  }
}
